negative_controls.command:
python3 -c 'from dharma_swarm.mission_control_contract import GOVERNED_PATCH_COMPLETION_CONTRACT, MissionControlError, completion_contract_from_metadata
assert completion_contract_from_metadata({}) == ""
assert completion_contract_from_metadata({"completion_contract": GOVERNED_PATCH_COMPLETION_CONTRACT}) == GOVERNED_PATCH_COMPLETION_CONTRACT
for bad in ("governed_patch_effect", "GOVERNED_PATCH_EFFECT_V1", True, 1):
    try:
        completion_contract_from_metadata({"completion_contract": bad})
    except MissionControlError:
        pass
    else:
        raise AssertionError(f"completion-contract alias accepted: {bad!r}")'
